<script>(function(){
var b=document.getElementById('shBurger'),n=document.getElementById('shNav'),head=document.querySelector('.site-head');
function closeMenu(){n.classList.remove('open');b.classList.remove('open');b.setAttribute('aria-expanded','false')}
b.addEventListener('click',function(e){e.stopPropagation();var o=n.classList.toggle('open');b.classList.toggle('open',o);b.setAttribute('aria-expanded',o)});
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeMenu()});
document.addEventListener('click',function(e){if(!head.contains(e.target))closeMenu()});
function offset(){return head.offsetHeight+10}
function go(h){
  if(h==='#top'||h==='#'){window.scrollTo({top:0,behavior:'smooth'});return}
  var el=document.getElementById(h.slice(1));if(!el)return;
  function target(){return Math.max(0,el.getBoundingClientRect().top+window.pageYOffset-offset())}
  window.scrollTo({top:target(),behavior:'smooth'});
  [600,1200,1800].forEach(function(ms){setTimeout(function(){var d=target()-window.pageYOffset;if(Math.abs(d)>3)window.scrollTo({top:target(),behavior:'smooth'})},ms)});
}
document.addEventListener('click',function(e){
  var a=e.target.closest?e.target.closest('a[href^="#"]'):null;if(!a)return;
  var h=a.getAttribute('href');if(!h||h.length<1)return;
  e.preventDefault();closeMenu();go(h);
  try{history.replaceState(null,'',h==='#top'?location.pathname+location.search:h)}catch(_){}
});
window.addEventListener('DOMContentLoaded',function(){
  var links=[].slice.call(n.querySelectorAll('a:not(.sh-cta)'));
  var map=links.map(function(a){return document.getElementById(a.getAttribute('href').slice(1))});
  function spy(){
    var y=window.pageYOffset+offset()+30,cur=0;
    map.forEach(function(el,i){if(i>0&&el&&el.getBoundingClientRect().top+window.pageYOffset<=y)cur=i});
    if(window.pageYOffset<40)cur=0;
    if(window.innerHeight+window.pageYOffset>=document.documentElement.scrollHeight-6)cur=links.length-1;
    links.forEach(function(a,i){a.classList.toggle('act',i===cur)});
  }
  window.addEventListener('scroll',spy,{passive:true});window.addEventListener('resize',spy);spy();
  if(location.hash.length>1){setTimeout(function(){go(location.hash)},350)}
});
})();</script>
